// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract ItemRegistry {
    struct Item {
        uint256 itemId;
        string category;
        string itemInfo;
        string owner;
        bool exists;
    }

    mapping(uint256 => Item) private items;
    uint256 private itemCounter;

    event ItemAdded(uint256 itemId, string category, string owner);

    function addItem(
        string memory _category,
        string memory _itemInfo,
        string memory _publicKey
    ) public returns (uint256) {
        itemCounter++;
        uint256 newItemId = itemCounter;

        items[newItemId] = Item({
            itemId: newItemId,
            category: _category,
            itemInfo: _itemInfo,
            owner: _publicKey,
            exists: true
        });

        emit ItemAdded(newItemId, _category, _publicKey);

        return newItemId;
    }

    function getItem(uint256 _itemId)
        public
        view
        returns (
            string memory category,
            string memory itemInfo,
            string memory owner
        )
    {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        return (item.category, item.itemInfo, item.owner);
    }

    function updateItemOwner(uint256 _itemId, string memory _newOwner) public {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        item.owner = _newOwner;
    }

    function updateItemInfo(uint256 _itemId, string memory _newInfo) public {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        item.itemInfo = _newInfo;
    }

    function getItemCategory(uint256 _itemId)
        public
        view
        returns (
            string memory category
        )
    {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        return (item.category);
    }

    function getItemOwner(uint256 _itemId)
        public
        view
        returns (
            string memory owner
        )
    {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        return (item.owner);
    }

    function getItemInfo(uint256 _itemId)
        public
        view
        returns (
            string memory itemInfo
        )
    {
        require(items[_itemId].exists, "item_not_exist");
        Item storage item = items[_itemId];
        return (item.itemInfo);
    }
}

